lab.solution:
def move(items, current, step):
    if not items:
        raise ValueError('need at least one item')
    return (current + step) % len(items)

items = ['a', 'b', 'c', 'd']
assert move(items, 3, 1) == 0
assert move(items, 0, -1) == 3
assert move(items, 0, 6) == 2
try:
    move([], 0, 1)
except ValueError:
    pass
else:
    raise AssertionError('empty cycle accepted')
print('cyclic indices checked')

